def sumSubarrayXors(nums):
    MOD = 10**9 + 7
    px = [0]
    for x in nums:
        px.append(px[-1] ^ x)
    m = len(px)
    total = 0
    for b in range(30):
        c = 0
        for v in px:
            c += (v >> b) & 1
        total += c * (m - c) * (1 << b)
    return total % MOD
